import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const c=JSON.parse('{"title":"Strategy — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"strategy-02-how-tos-and-workflows.md","filePath":"strategy-02-how-tos-and-workflows.md"}'),i={name:"strategy-02-how-tos-and-workflows.md"};function n(l,e,s,h,g,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="strategy-—-how-tos-workflows" tabindex="-1">Strategy — How-tos &amp; Workflows <a class="header-anchor" href="#strategy-—-how-tos-workflows" aria-label="Permalink to &quot;Strategy — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Strategy workflows</em></p><hr><h2 id="creating-a-strategy" tabindex="-1">Creating a Strategy <a class="header-anchor" href="#creating-a-strategy" aria-label="Permalink to &quot;Creating a Strategy&quot;">​</a></h2><ol><li>Navigate to the Strategy module from the left-hand navigation.</li><li>Create a new Strategy and give it a name. Names can be changed at any time.</li><li>Choose your approach — <strong>Top-Down</strong> or <strong>Bottom-Up</strong>. This cannot be changed after creation, so choose deliberately.</li><li>Define your three strategic dimensions. The defaults are Products and Services, Customer Segmentation, and Geographic Expansion — rename them to match your organization&#39;s priorities.</li><li>Set the time horizon and interval (e.g. 3 years, quarterly).</li><li>Lodestone generates the table with your dimensions as columns and your intervals as rows.</li></ol><hr><h2 id="building-a-top-down-strategy" tabindex="-1">Building a Top-Down Strategy <a class="header-anchor" href="#building-a-top-down-strategy" aria-label="Permalink to &quot;Building a Top-Down Strategy&quot;">​</a></h2><p>In a top-down strategy, you fill in the table manually with plain numbers representing relative investment emphasis.</p><ol><li>Click into any cell in the strategy table.</li><li>Enter a number representing your relative investment in that dimension during that interval. Numbers are unitless — they represent emphasis, not headcount or budget.</li><li>Repeat for each cell across all intervals.</li></ol><p>As you fill in values, the growth cube updates to reflect the allocation across your three dimensions at each point in time.</p><blockquote><p><strong>Tip:</strong> Consistency matters more than precision. If you use a scale of 1–10, stick to it throughout. The numbers only mean something relative to each other — a 7 next to a 3 tells a story; a 7 in isolation doesn&#39;t.</p></blockquote><hr><h2 id="building-a-bottom-up-strategy" tabindex="-1">Building a Bottom-Up Strategy <a class="header-anchor" href="#building-a-bottom-up-strategy" aria-label="Permalink to &quot;Building a Bottom-Up Strategy&quot;">​</a></h2><p>In a bottom-up strategy, each cell is populated by selecting Features from your backlog that match the dimension&#39;s tag.</p><ol><li>Each strategic dimension maps to a Feature tag — ensure your Features are tagged appropriately in the backlog before building your strategy.</li><li>Click into a cell in the strategy table.</li><li>Select Features from the backlog that belong to this dimension in this time interval.</li><li>Lodestone aggregates the selected Features&#39; evaluation scores into a cell value.</li><li>Toggle between <strong>Value</strong> and <strong>Effort</strong> to see the same strategy through two different lenses.</li></ol><blockquote><p><strong>Tip:</strong> The quality of a bottom-up strategy depends directly on the consistency of your Feature tagging. If Features aren&#39;t tagged, they won&#39;t surface when you&#39;re building your strategy table.</p></blockquote><hr><h2 id="adding-a-comment-to-a-time-interval" tabindex="-1">Adding a Comment to a Time Interval <a class="header-anchor" href="#adding-a-comment-to-a-time-interval" aria-label="Permalink to &quot;Adding a Comment to a Time Interval&quot;">​</a></h2><p>Each time interval has an optional Comment field. Comments appear as text on the corresponding slide when the Strategy is exported as a PPT.</p><ol><li>Click the Comment field for a time interval.</li><li>Enter a short note capturing the narrative context for that interval — what is the strategic focus, what is shifting, and why.</li></ol><p>Comments are particularly valuable in exported presentations, where they give each slide a narrative anchor beyond the growth cube visual.</p><hr><h2 id="editing-axis-names" tabindex="-1">Editing Axis Names <a class="header-anchor" href="#editing-axis-names" aria-label="Permalink to &quot;Editing Axis Names&quot;">​</a></h2><p>Strategic dimension names can be changed at any time, even after the strategy table has been populated.</p><ol><li>Click the axis name at the top of the relevant column.</li><li>Edit the name directly.</li></ol><p>Renaming an axis does not affect any values in the table — it only changes the label.</p><hr><h2 id="adding-or-removing-time-intervals" tabindex="-1">Adding or Removing Time Intervals <a class="header-anchor" href="#adding-or-removing-time-intervals" aria-label="Permalink to &quot;Adding or Removing Time Intervals&quot;">​</a></h2><p>Time intervals (rows) can be added or removed after a strategy has been created.</p><ul><li>To <strong>add</strong> an interval, use the option to append a row to the table.</li><li>To <strong>remove</strong> an interval, delete the relevant row.</li></ul><blockquote><p><strong>Note:</strong> Removing an interval permanently deletes any values or Feature selections in that row. There is no undo.</p></blockquote><hr><h2 id="viewing-the-growth-cube" tabindex="-1">Viewing the Growth Cube <a class="header-anchor" href="#viewing-the-growth-cube" aria-label="Permalink to &quot;Viewing the Growth Cube&quot;">​</a></h2><p>The growth cube visualization is available alongside the strategy table.</p><ul><li>Use the <strong>play</strong> button to animate through intervals automatically</li><li>Use the <strong>manual step</strong> controls to move through intervals one at a time</li></ul><p>Stepping through manually is useful when presenting — it lets you pause at each interval and narrate the strategic shift before moving on.</p><hr><h2 id="renaming-a-strategy" tabindex="-1">Renaming a Strategy <a class="header-anchor" href="#renaming-a-strategy" aria-label="Permalink to &quot;Renaming a Strategy&quot;">​</a></h2><p>Strategy names can be edited at any time. Click the Strategy name to edit it directly.</p><hr><h2 id="archiving-a-strategy" tabindex="-1">Archiving a Strategy <a class="header-anchor" href="#archiving-a-strategy" aria-label="Permalink to &quot;Archiving a Strategy&quot;">​</a></h2><p>When a Strategy is no longer active:</p><ol><li>Open the Strategy settings or options menu.</li><li>Select Archive.</li></ol><p>Archiving removes the Strategy from your active list but preserves it for reference. Features associated with the Strategy remain in your backlog unaffected.</p><hr><h2 id="exporting-a-strategy" tabindex="-1">Exporting a Strategy <a class="header-anchor" href="#exporting-a-strategy" aria-label="Permalink to &quot;Exporting a Strategy&quot;">​</a></h2><p>Strategies can be exported as a PPT slide deck or as Markdown.</p><h3 id="ppt-export" tabindex="-1">PPT export <a class="header-anchor" href="#ppt-export" aria-label="Permalink to &quot;PPT export&quot;">​</a></h3><ol><li>Open the Strategy you want to export.</li><li>Select the export option.</li><li>Choose your audience setting: <ul><li>Internal general</li><li>Internal executive</li><li>External</li></ul></li><li>Optionally enable AI-generated text descriptions and speaker notes.</li><li>Generate the export.</li></ol><p>The resulting PPT includes one slide per interval. Bottom-up strategies also include a list of the Features selected for each interval per dimension.</p><h3 id="markdown-md-export" tabindex="-1">Markdown (.md) export <a class="header-anchor" href="#markdown-md-export" aria-label="Permalink to &quot;Markdown (.md) export&quot;">​</a></h3><p>Click the Markdown export button (<code>.md</code>) in the export toolbar to download the Strategy as a structured Markdown document. Each time interval and its values are represented as text, suitable for pasting into Notion, Confluence, GitHub, or any Markdown-friendly tool.</p><h3 id="html-shareable-link" tabindex="-1">HTML (shareable link) <a class="header-anchor" href="#html-shareable-link" aria-label="Permalink to &quot;HTML (shareable link)&quot;">​</a></h3><p>Click <strong>Export as HTML</strong> in the export toolbar to generate a responsive, server-rendered HTML snapshot of your Strategy and receive a shareable <code>/share/...</code> URL. Anyone with the link can view the Strategy in a browser without logging in to Lodestone. Each generation produces a new URL.</p><hr><p><em>Next: Advanced Features &amp; Customization — top-down vs bottom-up in depth, axis design, and getting the most from exports.</em></p>',56)])])}const p=t(i,[["render",n]]);export{c as __pageData,p as default};
